{
  "findings": [
    {
      "check_id": "CKV_AZURE_40",
      "title": "Ensure that the expiration date is set on all keys",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key resource does not define an 'expiration_date', which means the key will never expire. This violates security best practices for key lifecycle management and rotation."
    },
    {
      "check_id": "CKV_AZURE_112",
      "title": "Ensure that key vault key is backed by HSM",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key is created with default software protection ('hsm' attribute is missing or false). For production secrets and keys, Hardware Security Module (HSM) backing provides stronger physical security guarantees against extraction."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_key\" \"generated\" {\n  name         = \"terragoat-generated-certificate-${var.environment}\"\n  key_vault_id = azurerm_key_vault.example.id\n  key_type     = \"RSA\"\n  key_size     = 2048\n  hsm          = true\n  expiration_date = timeadd(timestamp(), \"8760h\")\n  key_opts = [\n    \"decrypt\",\n    \"encrypt\",\n    \"sign\",\n    \"unwrapKey\",\n    \"verify\",\n    \"wrapKey\",\n  ]\n}",
  "fix_summary": "Added 'hsm = true' to ensure the key is backed by a Hardware Security Module. Added 'expiration_date' using 'timeadd' to set a one-year expiry, ensuring proper key lifecycle management."
}
